-- Generated by Murakumo: load tpch_erp.region (full), without Murakumo. Run it from the project folder.

-- The files under landing/tpch_erp/region/ that were not loaded before.
-- Loaded in full: each run fetched the whole table, so only the latest run's files count.
create or replace temp table new_rows as
select cast(r_regionkey as INTEGER) as r_regionkey, cast(r_name as VARCHAR) as r_name, cast(r_comment as VARCHAR) as r_comment, filename
from read_json('landing/tpch_erp/region/region_*.jsonl', format = 'newline_delimited', filename = true, columns = {'r_regionkey': 'INTEGER', 'r_name': 'VARCHAR', 'r_comment': 'VARCHAR'})
where regexp_extract(filename, '_(\d{8}T\d{12}Z)_', 1) = (select max(regexp_extract(file, '_(\d{8}T\d{12}Z)_', 1)) from glob('landing/tpch_erp/region/region_*.jsonl'))
  and parse_filename(filename) not in (select parse_filename(path) from audit.loaded_files where table_name = 'region');
-- When the latest run is new, its rows replace the table's.
delete from raw_tpch_erp.region where exists (select 1 from new_rows);
insert into raw_tpch_erp.region (r_regionkey, r_name, r_comment, _ingested_at, _batch_id)
select r_regionkey, r_name, r_comment, now(), parse_filename(filename) from new_rows;
-- Remember the files, so the next run skips them.
insert into audit.loaded_files (table_name, path, size, sha256, rows_ingested, batch_id, loaded_at)
select 'region', filename, null, null, count(*), parse_filename(filename), now()
from new_rows group by filename;
drop table new_rows;
